/// <summary>
/// VendEditInvoice form extension
/// </summary>
[ExtensionOf(formStr(VendEditInvoice))]
final class METVendEditInvoiceForm_Extension
{
}

Method.Source:
    /// <summary>
    /// Registers custom edit method for reason code field
    /// </summary>
    public void init()
    {
        next init();

        METeditReasonCode.registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(VendEditInvoice, metEditReasonCodeLookup));
        METeditReasonCode.registerOverrideMethod(methodStr(FormDataObject, jumpRef), formMethodStr(VendEditInvoice, metEditReasonCodejumpRef));
        METeditReasonCode.registerOverrideMethod(methodStr(FormDataObject, validate), formMethodStr(VendEditInvoice, metEditReasonCodeValidate));

        METeditPriceReasonCode.registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(VendEditInvoice, metEditPriceReasonCodeLookup));
    }

/// <summary>
/// METReasonCode lookup for quantity reason
/// </summary>
/// <param name="_formControl">Form control</param>
public void metEditReasonCodeLookup(FormStringControl _formControl)
{
    this.metLookupReasonCode(_formControl);
}

/// <summary>
/// METReasonCode lookup for price reason
/// </summary>
/// <param name="_formControl">Form control</param>
public void metEditPriceReasonCodeLookup(FormStringControl _formControl)
{
    this.metLookupReasonCode(_formControl);
}

    /// <summary>
    /// Filters the reason code lookup to exclude No Delivery reason codes
    /// </summary>
    /// <param name="_formControl">Form control</param>
    private void metLookupReasonCode(FormStringControl _formControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    dsReasonTable;
        // Instantiate sysTableLookup object using table which will provide the visible fields
        SysTableLookup  sysTableLookup = SysTableLookup::newParameters(tableNum(ReasonTable), _formControl);
        
        // Create the query
        dsReasonTable = query.addDataSource(tableNum(ReasonTable));

        if(true)
        {
            ReasonFormTable::setAccountRange(LedgerJournalACType::Vend, dsReasonTable);
        }

        if (false)
        {
            ReasonFormTable::setAccountRange(LedgerJournalACType::Vend, dsReasonTable);
        }

        if (false)
        {
            ReasonFormTable::setAccountRange(LedgerJournalACType::Ledger, dsReasonTable);
        }

        dsReasonTable.addRange(fieldNum(ReasonTable, METVarianceType)).value(strFmt('!= %1', any2int(METVarianceType::QuantityVarianceNoDelivery)));

        // Set the query to be used by the lookup form
        sysTableLookup.parmQuery(query);

        // Specify the fields to show in the form
        sysTableLookup.addLookupfield(fieldNum(ReasonTable, Reason));
        sysTableLookup.addLookupfield(fieldNum(ReasonTable, Description));

        // Perform the lookup
        sysTableLookup.performFormLookup();
    }

/// <summary>
/// METReasonCode jumpref
/// </summary>
/// <param name="_formControl">Form control</param>
public void metEditReasonCodejumpRef(FormStringControl _formControl)
{
    ReasonTable::jumpRef(ReasonCodeAccountTypeAll::Vend);
}

    /// <summary>
    /// METReasonCode validate
    /// </summary>
    /// <param name="_formControl">Form control</param>
    /// <returns>True/false</returns>
    public boolean metEditReasonCodeValidate(FormStringControl _formControl)
    {
        boolean ret = ReasonTable::validateReasonCode(_formControl.text(), LedgerJournalACType::Vend, true, LedgerJournalACType::Vend);

        if(ret && _formControl.text())
        {
            if(!ReasonTable::find(_formControl.text()).METInvoiceMatch)
            {
                ret = checkFailed("@MET:ReasonInvMatchingError");
            }
            if (!ReasonTable::find(_formControl.text()).METItem)
            {
                ret = checkFailed("@MET:METReasonCodeServiceItemError");
            }
        }
        
        return ret;
    }

/// <summary>
/// Get the PurchFormLetter_Invoice class instance
/// </summary>
/// <returns>PurchFormLetter_Invoice instance</returns>
public PurchFormLetter_Invoice metGetPurchFormLetter()
{
    return purchFormLetter;
}
